// Basic input validation before spending an LLM call
const body = $input.item.json.body || $input.item.json;
const required = ['property_id', 'document_type_hint', 'mime_type', 'file_base64'];
const missing = required.filter((f) => !body[f]);

if (missing.length > 0) {
  throw new Error(`Missing required field(s): ${missing.join(', ')}`);
}

const SUPPORTED_MIME_TYPES = ['application/pdf', 'image/png', 'image/jpeg', 'image/webp'];
if (!SUPPORTED_MIME_TYPES.includes(body.mime_type)) {
  throw new Error(`Unsupported mime_type: ${body.mime_type}. Supported: ${SUPPORTED_MIME_TYPES.join(', ')}`);
}

return {
  json: {
    property_id: body.property_id,
    document_type_hint: body.document_type_hint,
    mime_type: body.mime_type,
    // Internal flag - mapped to OpenAI's actual input_file/input_image type names in the next node
    content_block_type: body.mime_type === 'application/pdf' ? 'document' : 'image',
    file_base64: body.file_base64,
    uploaded_at: new Date().toISOString()
  }
};

