={{ {
  "model": "gpt-4.1",
  "instructions": "You extract structured data from German landlord documents. Return ONLY valid JSON with fields: document_type, category, confidence (0-1, your own honest estimate of extraction reliability for THIS document), and extracted_fields (an object). For rent receipts, EMI/mortgage statements, or Nebenkosten invoices, extracted_fields should include amount_eur, currency, issue_date. For rental contracts/lease agreements, extracted_fields should include tenant_name, landlord_name, property_address, monthly_rent_eur, deposit_eur, lease_start_date, lease_end_date_or_notice_period, special_clauses (array of strings). If a field cannot be read confidently, omit it rather than guessing.",
  "input": [
    {
      "role": "user",
      "content": [
        { "type": "input_text", "text": "Document type hint: " + $json.document_type_hint + ". Extract the structured fields as JSON." },
        $json.content_block_type === 'document'
          ? { "type": "input_file", "filename": "upload.pdf", "file_data": "data:" + $json.mime_type + ";base64," + $json.file_base64 }
          : { "type": "input_image", "image_url": "data:" + $json.mime_type + ";base64," + $json.file_base64 }
      ]
    }
  ]
} }}

